static size_t cpu_quota_cap(size_t hw){
    char path[4096]="/sys/fs/cgroup",line[4096];
    FILE *f=fopen("/proc/self/cgroup","r");
    if(f){while(fgets(line,sizeof(line),f))if(!strncmp(line,"0::/",4)){
        char *q=line+3;q[strcspn(q,"\n")]=0;
        if(!strstr(q,"/../")&&!strstr(q,"/./")&&strlen(path)+strlen(q)+10<sizeof(path)){
            if(strcmp(q,"/"))strcat(path,q);
        }break;
    }fclose(f);}
    for(;;){char file[4096];int n=snprintf(file,sizeof(file),"%s/cpu.max",path);
        if(n>0&&(size_t)n<sizeof(file)){f=fopen(file,"r");if(f){unsigned long long quota,period;if(fscanf(f,"%llu %llu",&quota,&period)==2&&period&&quota){unsigned long long k=quota/period;if(!k)k=1;if(k<hw)hw=(size_t)k;}fclose(f);}}
        if(!strcmp(path,"/sys/fs/cgroup"))break;
        char *slash=strrchr(path,'/');if(!slash||slash<path+strlen("/sys/fs/cgroup"))break;*slash=0;
    }return hw;
}
static size_t cpu_limit(void){const char *raw=getenv("DOC_WORKERS");if(raw&&*raw&&*raw!='-'){char *end;errno=0;unsigned long long v=strtoull(raw,&end,10);if(!errno&&!*end&&v&&v<SIZE_MAX)return (size_t)v;}return SIZE_MAX;}
